<script setup lang="ts">defineProps<{pending?:boolean;error?:unknown;empty?:boolean;message?:string}>();defineEmits<{retry:[]}>()</script>
<template><div v-if="pending" class="loading-grid" role="status" aria-label="Загрузка"><div v-for="i in 4" :key="i" class="skeleton"/><span class="sr-only">Загружаем находки из архива…</span></div><div v-else-if="error" class="empty-state" role="alert"><AppIcon name="refresh" :size="36"/><h2>Архив ненадолго закрылся</h2><p>{{errorMessage(error)}}</p><button class="btn" @click="$emit('retry')">Попробовать ещё раз</button></div><div v-else-if="empty" class="empty-state"><AppIcon name="search" :size="36"/><h2>{{message||'Пока ничего не найдено'}}</h2><p>Попробуйте другой запрос или сбросьте фильтры.</p><slot/></div></template>
